        public Task<(double Mean, double StdDev)> AsyncStats(List<double> values, CancellationToken cancellationToken)
        {
            if (values == null || values.Count == 0)
                throw new ArgumentException("Values must contain at least one number.");

            return Task.Run(() =>
            {
                // Welford's algorithm: single pass, numerically stable.
                double mean = 0, m2 = 0;
                for (int i = 0; i < values.Count; i++)
                {
                    if ((i & 0xFFF) == 0) cancellationToken.ThrowIfCancellationRequested();
                    double delta = values[i] - mean;
                    mean += delta / (i + 1);
                    m2 += delta * (values[i] - mean);
                }
                return (mean, Math.Sqrt(m2 / values.Count));
            }, cancellationToken);
        }
